+// OTHRYSL2-002: Settings Store
+// Export createSettingsStore(filePath, defaults)
+// Node ESM stdlib only
+// defaults must be a plain JSON-safe object and is never mutated.
+// Return frozen API {get, set, all, reset, resetAll}
+
+// Missing override file means {} and read calls must not write.
+// Existing malformed JSON/non-object/array, unknown override keys, or override values whose broad type differs from the corresponding default must throw Error('STATE_CORRUPT') and mutations must not overwrite it.
+// Allowed keys are exactly Object.keys(defaults).
+// Type classes: array, null, string, number(finite), boolean, object(plain);
+// set unknown key => Error('UNKNOWN_SETTING'), type mismatch/non-JSON/cycle => Error('SETTING_TYPE')
+// get/all return deep clones so caller mutation cannot mutate defaults or persisted state.
+// set persists only overrides, not merged defaults.
+// reset(key) deletes that override and persists; resetAll persists {}.
+// All mutations atomically mkdir dirname, write UTF8 JSON to unique same-directory temp, rename, cleanup temp on failure.
+// Deterministic, no network/deps/secrets.
+// Touch no other file.
+
+import { existsSync, mkdirSync, writeFileSync, renameSync, rmSync } from 'fs';
+import { join } from 'path';
+import { deepClone } from 'util';
+
+export function createSettingsStore(filePath, defaults) {
+  const allowedKeys = Object.keys(defaults);
+  const defaultValues = Object.fromEntries(allowedKeys.map(key => [key, defaults[key]]));
+  const defaultTypeMap = Object.fromEntries(allowedKeys.map(key => [key, typeof defaults[key]]));
+  const defaultDeepClone = deepClone(defaultValues);
+  const defaultDeepCloneTypeMap = deepClone(defaultTypeMap);
+
+  function validateValue(key, value) {
+    if (!allowedKeys.includes(key)) {
+      throw new Error('UNKNOWN_SETTING');
+    }
+    const expectedType = defaultTypeMap[key];
+    if (value === null) {
+      if (expectedType !== 'object' && expectedType !== 'null') {
+        throw new Error('SETTING_TYPE');
+      }
+    } else if (typeof value === 'object' && value !== null) {
+      if (expectedType !== 'object') {
+        throw new Error('SETTING_TYPE');
+      }
+      // Check if the value is a plain object
+      if (Object.getPrototypeOf(value) !== Object.prototype) {
+        throw new Error('SETTING_TYPE');
+      }
+    } else if (typeof value === 'number') {
+      if (Number.isNaN(value)) {
+        throw new Error('SETTING_TYPE');
+      }
+      if (expectedType !== 'number') {
+        throw new Error('SETTING_TYPE');
+      }
+    } else if (typeof value === 'string') {
+      if (expectedType !== 'string') {
+        throw new Error('SETTING_TYPE');
+      }
+    } else if (typeof value === 'boolean') {
+      if (expectedType !== 'boolean') {
+        throw new Error('SETTING_TYPE');
+      }
+    } else {
+      if (expectedType !== 'undefined') {
+        throw new Error('SETTING_TYPE');
+      }
+    }
+  }
+
+  function readState() {
+    if (!existsSync(filePath)) {
+      return defaultDeepClone;
+    }
+    try {
+      const fileContent = readFileSync(filePath, 'utf-8');
+      const parsedContent = JSON.parse(fileContent);
+      const clonedParsedContent = deepClone(parsedContent);
+      return clonedParsedContent;
+    } catch (error) {
+      if (error instanceof SyntaxError) {
+        throw new Error('STATE_CORRUPT');
+      }
+      throw error;
+    }
+  }
+
+  function writeState(state) {
+    const dirPath = join(...filePath.split('/').slice(0, -1));
+    if (!existsSync(dirPath)) {
+      mkdirSync(dirPath, { recursive: true });
+    }
+    const tempFilePath = filePath + '.tmp';
+    try {
+      writeFileSync(tempFilePath, JSON.stringify(state, null, 2), 'utf-8');
+      renameSync(tempFilePath, filePath);
+    } catch (error) {
+      rmSync(tempFilePath, { force: true });
+      throw error;
+    }
+  }
+
+  function get(key) {
+    const state = readState();
+    const value = state[key];
+    if (value === undefined) {
+      return deepClone(defaultDeepClone[key]);
+    }
+    return deepClone(value);
+  }
+
+  function set(key, value) {
+    validateValue(key, value);
+    const state = readState();
+    state[key] = value;
+    writeState(state);
+  }
+
+  function all() {
+    const state = readState();
+    return deepClone(state);
+  }
+
+  function reset(key) {
+    const state = readState();
+    if (state[key] === undefined) {
+      throw new Error('UNKNOWN_SETTING');
+    }
+    delete state[key];
+    writeState(state);
+  }
+
+  function resetAll() {
+    writeState(defaultDeepClone);
+  }
+
+  return Object.freeze({ get, set, all, reset, resetAll });
+}

